  'Study public administration as a field, profession, and public service, covering administrative theory, public value, and democratic accountability; bureaucracy, administrative politics, and the administrative state; public organizations and organizational behavior; leadership, public service motivation, and collaborative governance; policy implementation and street-level bureaucracy; budgeting, finance, procurement, and contract management; personnel, labor relations, and workforce strategy; administrative law, rulemaking, and compliance; ethics, equity, race, legitimacy, and administrative burden; performance management, evaluation, and evidence; digital government and cyber-risk; intergovernmental relations, networks, and emergency management; nonprofit and cross-sector administration; and comparative public administration, reform, and an applied capstone.',
  $padmjson${"slug": "public-administration", "title": "Public Administration", "description": "Study public administration as a field, profession, and public service, covering administrative theory, public value, and democratic accountability; bureaucracy, administrative politics, and the administrative state; public organizations and organizational behavior; leadership, public service motivation, and collaborative governance; policy implementation and street-level bureaucracy; budgeting, finance, procurement, and contract management; personnel, labor relations, and workforce strategy; administrative law, rulemaking, and compliance; ethics, equity, race, legitimacy, and administrative burden; performance management, evaluation, and evidence; digital government and cyber-risk; intergovernmental relations, networks, and emergency management; nonprofit and cross-sector administration; and comparative public administration, reform, and an applied capstone.", "topics": [{"id": "26b7ec9f-46c9-4bec-a159-b5c09e04b486", "type": "topic", "title": "Public Administration as Field, Profession, and Public Service", "description": "Students learn public administration as the practice of governing through public, nonprofit, and contracted institutions in service of public value.", "children": [{"id": "26053d84-5ccb-4f76-9232-f723a6926994", "type": "subtopic", "title": "Field and profession", "children": [{"id": "04bec771-2231-438e-83e7-4945d7651b8c", "type": "concept", "title": "Government, nonprofit, and contracted service delivery"}, {"id": "25aa8101-0d4c-4989-a378-b4fce0ba6ea3", "type": "concept", "title": "Public affairs, public management, policy, and administration distinctions"}, {"id": "06adfd93-2387-45f0-8693-5b3dda5d5ae0", "type": "concept", "title": "Career pathways and professional competencies"}], "description": "The point is to understand what public administrators do and why their work matters for democratic life."}, {"id": "3e7a6c31-5223-45de-957e-1b13126d4534", "type": "subtopic", "title": "Public service values", "children": [{"id": "7ae098db-d764-4585-a3c5-e67d2481d918", "type": "concept", "title": "Public interest and public value"}, {"id": "6dc4e14d-fbc2-4fd0-a029-9d71fa2b3303", "type": "concept", "title": "Equity, effectiveness, economy, transparency, and legality"}, {"id": "d75385bc-21be-41ed-bd15-670a04d4ce8b", "type": "concept", "title": "Public service motivation"}], "description": "Students learn that administrative work is guided by values, not only efficiency."}, {"id": "da4fdc97-53df-4f5c-abb4-4b316873d634", "type": "subtopic", "title": "Governance context", "children": [{"id": "671bf767-639d-4b7e-87c9-44427b296418", "type": "concept", "title": "Political oversight and public accountability"}, {"id": "f3430ec8-27c3-466c-9670-8d9e1a67afca", "type": "concept", "title": "Stakeholders and interest groups"}, {"id": "8b63e81b-5016-48e2-8f97-8fd3dd56c92c", "type": "concept", "title": "Cross-sector governance"}], "description": "Administrators operate in complex systems with elected officials, courts, communities, media, and partner organizations."}]}, {"id": "03f88355-01c0-41e6-b8de-e74b15f336ba", "type": "topic", "title": "Administrative Theory, Public Value, and Democratic Accountability", "description": "This module connects classic PA theory to modern debates about legitimacy, discretion, responsiveness, and public interest.", "children": [{"id": "4ad09839-b8bd-4fe1-8901-cd20568e81f0", "type": "subtopic", "title": "Classical foundations", "children": [{"id": "b5547494-65a1-495a-bf81-a9cf239f4c0c", "type": "concept", "title": "Wilson and politics-administration debates"}, {"id": "d694a8fc-8d64-4bec-93b6-7aad75ece296", "type": "concept", "title": "Weberian bureaucracy"}, {"id": "549c6ad7-7a12-4f53-9059-41dd2055a0bd", "type": "concept", "title": "Scientific management and administrative principles"}], "description": "Classic theory gives students a vocabulary for hierarchy, specialization, discretion, and rational administration."}, {"id": "8c053c77-27fc-45f6-8e1a-90a1593671a7", "type": "subtopic", "title": "Modern public administration", "children": [{"id": "20826828-393a-4670-9a67-ab51671146dd", "type": "concept", "title": "New Public Management"}, {"id": "054b6ba4-701a-4301-9bcb-7c7b4db7807e", "type": "concept", "title": "New Public Service"}, {"id": "98d4e1d0-7d0e-4129-886d-73e7e95ea1e5", "type": "concept", "title": "Public value management"}], "description": "Students compare newer frameworks that respond to complexity, citizens, and networks."}, {"id": "347f847a-6da5-4cd3-83da-6dfcaae85f95", "type": "subtopic", "title": "Accountability", "children": [{"id": "2891b4f4-570b-45a6-949b-c37237bc390d", "type": "concept", "title": "Hierarchical, legal, professional, and political accountability"}, {"id": "4af979e8-9e87-430f-bf01-d9fc974592a6", "type": "concept", "title": "Transparency and participation"}, {"id": "3f5e8d72-1f45-407d-a2b5-5311881bffa0", "type": "concept", "title": "Discretion and democratic control"}], "description": "Administrators must answer to law, elected officials, performance standards, and the public."}]}, {"id": "ba135152-1c94-43d9-9338-7e063eef128a", "type": "topic", "title": "Bureaucracy, Administrative Politics, and the Administrative State", "description": "Students examine how bureaucracies exercise authority, manage complexity, and operate inside political systems.", "children": [{"id": "93cc28f6-b0a0-406e-b55b-7654850d6ae0", "type": "subtopic", "title": "Bureaucratic institutions", "children": [{"id": "e64777bb-341a-419b-9811-eab910b6f3ab", "type": "concept", "title": "Hierarchy, expertise, routines, and standardization"}, {"id": "87784f6e-e676-4fad-93e1-26425c57e4ec", "type": "concept", "title": "Agency missions and organizational boundaries"}, {"id": "e3efe6f0-c1d6-41d7-b0e3-76fdae804d78", "type": "concept", "title": "Administrative capacity"}], "description": "Students learn why bureaucracy is both necessary and politically contested."}, {"id": "69850f72-3337-4739-86e1-0f151280e2db", "type": "subtopic", "title": "Administrative politics", "children": [{"id": "dc050da6-2604-40c1-b698-4ac394d6aaa8", "type": "concept", "title": "Principal-agent problems"}, {"id": "5b4813bc-4b2a-4351-a5b9-20815633505c", "type": "concept", "title": "Budget and jurisdiction politics"}, {"id": "288039d1-1cf3-4122-8ff3-677dda5284fb", "type": "concept", "title": "Agency autonomy and oversight"}], "description": "Public agencies bargain with elected officials, courts, clients, unions, contractors, and advocacy groups."}, {"id": "a4056a6b-86ac-4955-ae93-5e3705e678a4", "type": "subtopic", "title": "Reform movements", "children": [{"id": "411a760c-5b2d-4a44-9a73-14157977e542", "type": "concept", "title": "Civil service reform"}, {"id": "c7593d2b-b8ed-4853-b7fc-c2e1a4f40a8d", "type": "concept", "title": "Performance and results movements"}, {"id": "5be6eb79-71c7-464c-9994-f7741c54f5c2", "type": "concept", "title": "Privatization, outsourcing, and reinvention"}], "description": "Administrative reform reflects changing ideas about efficiency, accountability, and trust."}]}, {"id": "d01f693f-d81d-4e86-9856-9e2ed1a05131", "type": "topic", "title": "Public Organizations, Management, and Organizational Behavior", "description": "This topic develops tools for understanding structure, culture, motivation, decision-making, teams, and change in public agencies.", "children": [{"id": "be0b670b-468c-4df8-8b77-63addc8ae856", "type": "subtopic", "title": "Organizational design", "children": [{"id": "f5e203a3-5d65-48fc-8fc4-81f6cb3b8e4f", "type": "concept", "title": "Centralization and decentralization"}, {"id": "0a07a41f-c213-4d46-aac6-4b7420399adf", "type": "concept", "title": "Span of control and specialization"}, {"id": "0c5b7458-af5e-442b-8159-32e19cf0640c", "type": "concept", "title": "Formal rules and informal routines"}], "description": "Structure shapes coordination, communication, authority, and service quality."}, {"id": "f3487aff-3f1c-41e7-a943-31a3c3d2f59d", "type": "subtopic", "title": "Behavior and motivation", "children": [{"id": "d54692ce-61e2-46c9-9c28-7078fc792af2", "type": "concept", "title": "Bounded rationality"}, {"id": "5861c6ad-e8d4-4a06-a152-c441dc522b17", "type": "concept", "title": "Public service motivation and incentives"}, {"id": "c21c2c2d-3b93-4124-a125-1ec1be284bc8", "type": "concept", "title": "Culture, morale, and psychological safety"}], "description": "Students learn how people behave inside public organizations under real constraints."}, {"id": "f3d4dc0c-4fed-49ad-8110-f25c6735cee0", "type": "subtopic", "title": "Change management", "children": [{"id": "ff7eeb8a-d135-4b67-88be-6b8d9d7c90c2", "type": "concept", "title": "Implementation readiness"}, {"id": "4bf03702-a95e-41a9-bca6-ac6b484a755f", "type": "concept", "title": "Stakeholder buy-in"}, {"id": "9aebcbb9-06ce-45cf-b430-26c1ce8b34a1", "type": "concept", "title": "Resistance, learning, and adaptation"}], "description": "Public managers must improve organizations while maintaining legitimacy and continuity."}]}, {"id": "28e15a48-a621-4386-a9dd-56f7258086ac", "type": "topic", "title": "Leadership, Public Service Motivation, and Collaborative Governance", "description": "Students learn leadership as an ethical, relational, and cross-boundary practice rather than just formal authority.", "children": [{"id": "32b046b4-dee1-4da3-82f9-84cb956f4168", "type": "subtopic", "title": "Public leadership", "children": [{"id": "8a99f739-2fad-4e5c-be91-1e961aa6e69e", "type": "concept", "title": "Ethical leadership"}, {"id": "4d6884a3-2eae-4523-9927-da3c0ddcea76", "type": "concept", "title": "Adaptive leadership"}, {"id": "8c4853d8-1840-408d-b886-7ad3182bf5d0", "type": "concept", "title": "Strategic communication and trust"}], "description": "Leadership in PA is about stewarding values, people, and institutions under public scrutiny."}, {"id": "6ffbe452-7fb3-464a-ae55-9109492a4533", "type": "subtopic", "title": "Collaboration", "children": [{"id": "c596b01c-2bc4-4302-b321-59ab5ebc0d92", "type": "concept", "title": "Interagency coordination"}, {"id": "56599b96-3c8e-4255-948d-3d9c746587d3", "type": "concept", "title": "Network governance"}, {"id": "ceafeed5-b2b6-4cf6-b1f8-ce2ccf3fe1b1", "type": "concept", "title": "Shared goals, roles, and accountability"}], "description": "Many public problems require agencies and sectors to work together."}, {"id": "972a3180-77f4-4f9d-adb2-92cfe4131eef", "type": "subtopic", "title": "Professional identity", "children": [{"id": "b512dd40-baab-44ff-9845-1be37e0d094d", "type": "concept", "title": "Competency planning"}, {"id": "e52e78e0-0ed8-406f-9419-04e23f1fbc57", "type": "concept", "title": "Civic humility and service orientation"}, {"id": "87837a71-5b8e-4d19-ae93-6435f4e62fe0", "type": "concept", "title": "Burnout, resilience, and public workforce morale"}], "description": "Students develop a reflective sense of public-service responsibility."}]}, {"id": "62cbc41a-6159-439d-856c-066b70863190", "type": "topic", "title": "Policy Process, Implementation, and Street-Level Bureaucracy", "description": "This module shows how policy decisions become real services, rules, burdens, and outcomes through implementation.", "children": [{"id": "d81c546f-eefe-46cd-aa08-73817dd6bc9a", "type": "subtopic", "title": "Policy process", "children": [{"id": "b12c4a02-d5d7-4f18-b379-8cd681adb096", "type": "concept", "title": "Agenda setting and problem framing"}, {"id": "cbad910c-d474-4970-83b8-ce5d47c03fa0", "type": "concept", "title": "Policy design and instruments"}, {"id": "b4d6c5bd-edfe-46e1-a75a-9d148b5216e8", "type": "concept", "title": "Feedback, learning, and policy change"}], "description": "Students learn how problems move from agenda setting to adoption, implementation, and revision."}, {"id": "12879ea2-1be9-4cfe-aa4e-eab20779261a", "type": "subtopic", "title": "Implementation", "children": [{"id": "4af3a23e-2957-4a71-a89f-546aaaa58267", "type": "concept", "title": "Implementation capacity"}, {"id": "650b2545-4d4c-4e3a-ae76-42d9ba53c644", "type": "concept", "title": "Administrative procedures and eligibility"}, {"id": "1cb774cc-7ab7-4c3f-9f97-eea0f509e49b", "type": "concept", "title": "Implementation failure and adaptation"}], "description": "Implementation translates policy intent into rules, routines, budgets, and services."}, {"id": "dd899abc-7dc1-430b-8385-c451f0dda9f9", "type": "subtopic", "title": "Street-level bureaucracy", "children": [{"id": "119eb160-9e54-4d0d-a048-3454d3f75924", "type": "concept", "title": "Discretion and coping mechanisms"}, {"id": "50645e88-891a-4397-9394-ddc119164c7a", "type": "concept", "title": "Administrative burden and access"}, {"id": "79521165-2ba5-44f3-b3e0-b54d0b4fe354", "type": "concept", "title": "Client interaction and procedural justice"}], "description": "Frontline workers shape public policy through daily discretionary decisions."}]}, {"id": "da1de89f-7bb3-4775-b14d-bea2b940c151", "type": "topic", "title": "Public Budgeting, Finance, Procurement, and Contract Management", "description": "Students learn how budgets, revenues, purchasing, grants, and contracts shape what government can actually do.", "children": [{"id": "b804f808-1df1-4f2c-8f62-003e3163bb6d", "type": "subtopic", "title": "Budgeting", "children": [{"id": "8d5328e0-5f79-4426-b181-ca2d08fe2eb0", "type": "concept", "title": "Operating and capital budgets"}, {"id": "fbd1d67d-59bb-4213-b673-50a43b32302d", "type": "concept", "title": "Incremental, performance, and program budgeting"}, {"id": "ca182647-1e5c-4e06-8c55-0a06a4d7100b", "type": "concept", "title": "Budget calendar and executive-legislative negotiation"}], "description": "Budgets express priorities and constraints in a form that agencies must live with."}, {"id": "f20db2bb-8dcb-4496-a316-fb7d371a72a5", "type": "subtopic", "title": "Public finance", "children": [{"id": "690b0d12-f670-463b-bc28-3d7ab769fc8d", "type": "concept", "title": "Taxes, fees, intergovernmental transfers, and debt"}, {"id": "38a17ef8-2fa2-4e31-8b4f-50888a308880", "type": "concept", "title": "Fiscal federalism"}, {"id": "d74337cd-0b06-4b82-b8d3-449f4141840a", "type": "concept", "title": "Equity, efficiency, and sustainability"}], "description": "Students learn how revenue systems, debt, grants, and fiscal rules shape public capacity."}, {"id": "8e75ad0a-3fe2-4fb0-aa42-cd489d5483cb", "type": "subtopic", "title": "Procurement and contracts", "children": [{"id": "9ab91368-76ed-4868-8c37-0c8ee282bbc4", "type": "concept", "title": "RFPs, vendor selection, and competition"}, {"id": "2742a939-3fad-4b13-81e2-05206b0f7c88", "type": "concept", "title": "Contract incentives and monitoring"}, {"id": "779f27c1-077b-4013-b556-9afd069d2d9d", "type": "concept", "title": "Grants, compliance, and audit risk"}], "description": "Contracting is a governance tool with high stakes for performance and integrity."}]}, {"id": "c491bc69-fd58-4e53-a035-9a74ce2e5996", "type": "topic", "title": "Public Personnel, Human Resources, Labor Relations, and Workforce Strategy", "description": "This topic covers hiring, classification, unions, performance, equity, and workforce planning in public organizations.", "children": [{"id": "4ac4e511-a276-428a-9779-caf7a97e436a", "type": "subtopic", "title": "Civil service systems", "children": [{"id": "97bd2f17-4482-4004-9f43-856eea1f7cad", "type": "concept", "title": "Merit principles and classification"}, {"id": "4f021c20-c20c-4703-9fbd-f918b1079ac9", "type": "concept", "title": "Recruitment, selection, and onboarding"}, {"id": "1989c339-69c2-473f-8ea9-200ff3ed2e78", "type": "concept", "title": "Political neutrality and patronage risks"}], "description": "Students learn how public hiring tries to balance merit, equity, flexibility, and accountability."}, {"id": "0d0f6735-01ed-4be0-bfd1-65775327db65", "type": "subtopic", "title": "Workforce management", "children": [{"id": "237f3a3c-9969-475c-bf95-695fedb1ec76", "type": "concept", "title": "Performance appraisal"}, {"id": "e8a09f3e-8f9e-4ecf-b3b8-2cf5c27eee36", "type": "concept", "title": "Training and professional development"}, {"id": "a2db165c-a14f-4418-9545-ca0f7b5cd612", "type": "concept", "title": "Succession planning and workforce analytics"}], "description": "Public organizations need skilled, supported, and diverse workforces."}, {"id": "5d81f249-9b72-4965-a7d1-0c801715d1ab", "type": "subtopic", "title": "Labor relations", "children": [{"id": "18ffab5c-b100-4a1c-98b5-afa7c96b8793", "type": "concept", "title": "Collective bargaining"}, {"id": "64a225ac-f213-43eb-a575-96afce207d1e", "type": "concept", "title": "Grievance procedures"}, {"id": "5428f0e1-6a0f-4a09-be03-a41658c917a2", "type": "concept", "title": "Public-sector unions and management rights"}], "description": "Public labor relations shape budgets, service delivery, and workplace voice."}]}, {"id": "f9997a50-0968-4ad8-a914-a51b0353938c", "type": "topic", "title": "Administrative Law, Regulation, Rulemaking, and Compliance", "description": "Students learn the legal machinery that authorizes, constrains, and reviews administrative action.", "children": [{"id": "8200bc04-9a7e-44b8-9ed8-59b2524ab036", "type": "subtopic", "title": "Administrative authority", "children": [{"id": "b7ddd537-9c5e-40d8-959f-a47aff8d35b4", "type": "concept", "title": "Statutory delegation"}, {"id": "ea0df70a-4e7e-4ba8-b365-434b13dbc2d9", "type": "concept", "title": "Administrative discretion"}, {"id": "b27b48cb-b1d0-4ced-916b-5bf6f4d85f9c", "type": "concept", "title": "Due process and constitutional constraints"}], "description": "Students learn where agencies get power and what limits that power."}, {"id": "dad66370-009f-4ac7-baec-4910e513e0e7", "type": "subtopic", "title": "Rulemaking and adjudication", "children": [{"id": "82dcaeb5-edc0-46f7-8174-bd2de6c916e9", "type": "concept", "title": "Notice-and-comment rulemaking"}, {"id": "6c15a437-94a4-490e-b3d2-027cf390aa0a", "type": "concept", "title": "Public participation and records"}, {"id": "0ae18c0b-7c49-4d70-9e93-8c8d4a1d4e9c", "type": "concept", "title": "Adjudication and enforcement"}], "description": "Agencies make, interpret, and enforce rules through structured legal procedures."}, {"id": "681d25ea-68d4-4aca-979b-6bc05f244440", "type": "subtopic", "title": "Regulatory governance", "children": [{"id": "04503874-a7e3-4af1-881b-065a1ab93dcb", "type": "concept", "title": "Regulatory impact analysis"}, {"id": "41005147-be72-42e8-bdb0-a48f360dccfb", "type": "concept", "title": "Capture and accountability"}, {"id": "2966c629-71e5-4624-a52d-c0062faf0fbd", "type": "concept", "title": "Judicial review and standards of review"}], "description": "Regulation requires balancing benefits, costs, compliance, and legitimacy."}]}, {"id": "d3867baf-2655-4d78-b2ad-2c1d794ba1ff", "type": "topic", "title": "Ethics, Equity, Race, Legitimacy, and Administrative Burden", "description": "This module places justice, accountability, access, and trust at the center of public administration.", "children": [{"id": "26bde50f-e42a-461b-a870-34b27ea58456", "type": "subtopic", "title": "Public ethics", "children": [{"id": "08049d7a-1a6b-4d64-aa6f-ccf8abc1fb9a", "type": "concept", "title": "Conflicts of interest"}, {"id": "e9c230ef-1805-47ec-9e86-750939b2c2ad", "type": "concept", "title": "Whistleblowing and transparency"}, {"id": "8a0fb9e5-5f37-4add-a0db-abccc616703c", "type": "concept", "title": "Ethical tradeoffs under scarcity"}], "description": "Ethics gives administrators tools for acting responsibly under conflicting pressures."}, {"id": "7266d8d4-9776-4a96-a508-be471ff92086", "type": "subtopic", "title": "Equity and justice", "children": [{"id": "338c977f-aeb1-457c-8aa9-3c96099710c3", "type": "concept", "title": "Racial equity and policy history"}, {"id": "3348bd3b-3b2a-4296-ad4d-6e5ad908bae5", "type": "concept", "title": "Gender, disability, immigration, and intersectionality"}, {"id": "7560fa72-104d-4702-bba7-6dcd5755018a", "type": "concept", "title": "Equity impact assessment"}], "description": "Students learn to assess who benefits, who is burdened, and who is excluded."}, {"id": "76be510d-26e4-4785-9234-841c2fe26c67", "type": "subtopic", "title": "Administrative burden", "children": [{"id": "9fc01443-3c43-4d30-9626-064d52926881", "type": "concept", "title": "Learning, compliance, and psychological costs"}, {"id": "e763a238-5115-4e11-808b-40336b427af5", "type": "concept", "title": "Procedural justice and legitimacy"}, {"id": "95e94edb-35e7-4770-8b89-ead4c3281482", "type": "concept", "title": "Burden reduction and human-centered administration"}], "description": "Rules and procedures can quietly block access to public benefits and rights."}]}, {"id": "35668a47-14e4-4082-a4ca-c4876f8502bf", "type": "topic", "title": "Performance Management, Evaluation, Data, and Evidence-Informed Governance", "description": "Students learn to measure performance, evaluate programs, use administrative data, and communicate evidence responsibly.", "children": [{"id": "328f0895-efc4-4519-9035-455b557a4e55", "type": "subtopic", "title": "Performance systems", "children": [{"id": "10c006ea-a5d7-4c2b-8a45-a7cd467407d3", "type": "concept", "title": "Inputs, outputs, outcomes, and impacts"}, {"id": "9ee3a726-9169-40f9-b738-10c0bd497d23", "type": "concept", "title": "Performance dashboards"}, {"id": "916d32d3-31f8-4ca7-bd48-7f6edd6c273d", "type": "concept", "title": "Gaming, target fixation, and unintended consequences"}], "description": "Students learn how goals and indicators can improve or distort public work."}, {"id": "7b3dba18-1530-4973-b6d2-eaf98dc3ff0a", "type": "subtopic", "title": "Program evaluation", "children": [{"id": "d2546054-cae3-4a25-ad3c-916a4e5f7310", "type": "concept", "title": "Logic models"}, {"id": "7dfe1a2d-a6ef-48a0-a767-3adec0ded4cd", "type": "concept", "title": "Process, outcome, and impact evaluation"}, {"id": "d3a618f9-cc95-4fa4-aeb0-be2fb2bd4942", "type": "concept", "title": "Cost-effectiveness and implementation evaluation"}], "description": "Evaluation helps agencies learn whether programs work and for whom."}, {"id": "99caaf88-6977-4aa2-99dd-6fefc1d17659", "type": "subtopic", "title": "Data governance", "children": [{"id": "fbc2b363-98c0-4eaf-ae26-7d92f48b734e", "type": "concept", "title": "Open data and administrative datasets"}, {"id": "527f12fa-cb90-40fb-859c-6fc5a1e68c7b", "type": "concept", "title": "Data quality and privacy"}, {"id": "19c23827-1c48-45cb-bb57-4bb6a6af12b5", "type": "concept", "title": "Evidence communication for decision makers"}], "description": "Administrative data must be useful, ethical, secure, and interpretable."}]}, {"id": "6e5eddeb-b790-4419-b538-1d32a92c2b14", "type": "topic", "title": "Digital Government, Service Design, Technology, and Cyber-Risk", "description": "This topic examines e-government, digital services, data governance, AI-era administration, privacy, and cybersecurity risk.", "children": [{"id": "dd9362e3-99d9-4e5c-9444-09dce201e12b", "type": "subtopic", "title": "Digital services", "children": [{"id": "35fea6ab-4310-44a0-9649-b40ebede44b2", "type": "concept", "title": "E-government portals"}, {"id": "4a98526e-43f8-479b-8800-56e5d134ec1e", "type": "concept", "title": "Human-centered service design"}, {"id": "cc82883b-6d74-4a12-9217-d1009a349aef", "type": "concept", "title": "Accessibility and plain language"}], "description": "Students learn how technology changes access, operations, and public expectations."}, {"id": "f9be7a0e-4e93-4176-93ad-db688bca0543", "type": "subtopic", "title": "Technology governance", "children": [{"id": "fe7fbb65-685e-432d-baab-7257df29b731", "type": "concept", "title": "IT modernization"}, {"id": "a05bfcad-17e7-40f3-93c1-629be3e6d3ae", "type": "concept", "title": "Data sharing and interoperability"}, {"id": "c47dcdbb-6f51-4812-9a3e-059581ee2ce6", "type": "concept", "title": "Algorithmic accountability and AI governance"}], "description": "Digital tools require procurement, oversight, transparency, and risk management."}, {"id": "6b2ed459-1e25-4824-ad64-6e18079c6026", "type": "subtopic", "title": "Cyber and privacy risk", "children": [{"id": "ef0fbcda-2be0-4398-bdd2-648c25b6efe6", "type": "concept", "title": "Cybersecurity basics"}, {"id": "b77f6ebe-9c7c-46cc-af56-44a3e3bf6b87", "type": "concept", "title": "Privacy, records, and identity management"}, {"id": "5d927738-9db2-447a-95a9-abd7aa887f2a", "type": "concept", "title": "Continuity of operations"}], "description": "Public agencies must protect systems and people while delivering services."}]}, {"id": "9d50f36d-2621-49d0-a665-cd533ed75e7d", "type": "topic", "title": "Intergovernmental Relations, Federalism, Networks, and Emergency Management", "description": "Students compare governance across federal, state, local, regional, nonprofit, and private-sector networks.", "children": [{"id": "ef939666-0838-4e5d-9b2c-3bac53a2ea89", "type": "subtopic", "title": "Federalism and IGR", "children": [{"id": "c964c49c-5054-4d40-99ba-0e2dcd90d82c", "type": "concept", "title": "Federal, state, local, tribal, and regional roles"}, {"id": "1adc57f7-b9f8-4df2-b08d-0d1b51792fa1", "type": "concept", "title": "Mandates, grants, and preemption"}, {"id": "6454d0d9-e3dc-49ea-a38d-6e417532c75b", "type": "concept", "title": "Fiscal and administrative federalism"}], "description": "Students learn how authority and funding move across levels of government."}, {"id": "878b1a16-7f01-49ea-bed7-88a90e1c3a2f", "type": "subtopic", "title": "Networks", "children": [{"id": "3f93e2fe-8792-4aab-b6b8-7c1a5b4ddc82", "type": "concept", "title": "Regional governance"}, {"id": "21d23b7d-2637-41d0-95d1-6d96c3b191f7", "type": "concept", "title": "Public-private and nonprofit partners"}, {"id": "27aa66bf-2ca4-4f06-aefd-3bfdb1b1d809", "type": "concept", "title": "Network accountability"}], "description": "Public problems often sit across agency and jurisdictional boundaries."}, {"id": "f5fe10df-0e3d-4434-bb71-9f576f25625e", "type": "subtopic", "title": "Emergency management", "children": [{"id": "6342951e-9ff3-4ba8-afa1-b7cb1200e495", "type": "concept", "title": "Preparedness, response, recovery, and mitigation"}, {"id": "b4861829-0419-4b7c-8b1c-979e8d5b5603", "type": "concept", "title": "Incident command and coordination"}, {"id": "068754b0-c62a-4fcd-8855-69cea836fd4c", "type": "concept", "title": "Risk communication and equity in disasters"}], "description": "Crises reveal strengths and weaknesses in public administration."}]}, {"id": "2eae785d-e087-45fb-a45a-462519d18f2d", "type": "topic", "title": "Nonprofit, Philanthropic, and Cross-Sector Administration", "description": "This module expands public administration beyond government into nonprofit management, philanthropy, and public-private partnerships.", "children": [{"id": "929c6ec5-fa56-465f-9508-22866d2d80d1", "type": "subtopic", "title": "Nonprofit governance", "children": [{"id": "a4c73486-813d-4c64-b05b-bc31d752e79d", "type": "concept", "title": "Boards and executive leadership"}, {"id": "fec9a70b-0326-40e7-86f8-7ca02219401a", "type": "concept", "title": "Mission, accountability, and public trust"}, {"id": "81058018-b908-468a-abd6-0cac890be956", "type": "concept", "title": "Nonprofit legal and tax context"}], "description": "Students learn how mission-driven organizations complement and challenge government."}, {"id": "31988239-9697-4ebd-8a53-80c00102abe6", "type": "subtopic", "title": "Revenue and philanthropy", "children": [{"id": "3c73116a-078b-4c53-ac9f-46c1b674a74a", "type": "concept", "title": "Grants, contracts, donations, and earned revenue"}, {"id": "891b1347-d271-45be-9f72-645363c6a07d", "type": "concept", "title": "Fundraising ethics"}, {"id": "e48aaf2b-385a-48d6-8b2e-8537d765ec3c", "type": "concept", "title": "Restricted funding and compliance"}], "description": "Nonprofit sustainability depends on diverse and ethical funding strategies."}, {"id": "ea26a55e-5617-42d5-a099-2811c12cdc1b", "type": "subtopic", "title": "Cross-sector partnerships", "children": [{"id": "b9f41025-efa2-496b-a632-cdb3053e1d18", "type": "concept", "title": "Public-private partnerships"}, {"id": "08c655d8-3319-44cb-b265-61cfd0f5b706", "type": "concept", "title": "Shared performance metrics"}, {"id": "d84d1829-6522-442d-b830-f754ce8f1c84", "type": "concept", "title": "Contracting, collaboration, and community benefit"}], "description": "Partnerships can expand capacity but complicate accountability."}]}, {"id": "9433b296-6f6a-449b-8686-36d301c6e31e", "type": "topic", "title": "Comparative Public Administration, Reform, and Applied Capstone", "description": "Students synthesize the course through comparative governance, reform analysis, professional communication, and a practical capstone.", "children": [{"id": "8311003e-115e-4f2c-850f-5ef0b1474433", "type": "subtopic", "title": "Comparative PA", "children": [{"id": "9d16d574-b24b-495d-a421-541ec24d5485", "type": "concept", "title": "State capacity and corruption"}, {"id": "97ede826-dbb9-4de1-b98f-38372d0c7da4", "type": "concept", "title": "OECD, World Bank, and UN governance frameworks"}, {"id": "e8c32960-9e24-4dd7-b17e-a7319f1b9dc5", "type": "concept", "title": "Localization and participation"}], "description": "Students compare how administrative systems vary across countries and development contexts."}, {"id": "ddf4420c-46f7-4628-bdd8-0f2e9de79fcb", "type": "subtopic", "title": "Administrative reform", "children": [{"id": "22238631-8ade-4f7c-bbd5-c6234ec107df", "type": "concept", "title": "Civil service reform"}, {"id": "56ec7125-ac22-45cd-8f2e-348533d0c5aa", "type": "concept", "title": "Decentralization and anti-corruption"}, {"id": "c6af60da-8938-478e-97e7-9274af6a62f4", "type": "concept", "title": "Performance, digital, and service-delivery reforms"}], "description": "Reform requires diagnosing institutional problems and political constraints."}, {"id": "d90c1d1c-83da-4afd-9cf2-94c674d6d5f0", "type": "subtopic", "title": "Capstone", "children": [{"id": "de831019-1059-4aff-9fbd-a0f5a3bf1ff9", "type": "concept", "title": "Agency case diagnosis"}, {"id": "e0fa0b9b-a29f-4721-8a8f-eb1507b95698", "type": "concept", "title": "Budget, personnel, equity, legal, and performance analysis"}, {"id": "6d63e96b-1ae5-4eb0-b451-90ee80fdfdba", "type": "concept", "title": "Executive memo and presentation"}], "description": "The capstone turns course knowledge into a professional-quality administrative analysis."}]}], "dbBacked": true}$padmjson$::jsonb,
